function occupied(q,r,ignore){return state.units.find(u=>u.hp>0&&u.id!==ignore&&u.q===q&&u.r===r)}function reach(u){const out=new Map(),q=[{q:u.q,r:u.r,c:0}];out.set(key(u.q,u.r),0);while(q.length){const p=q.shift();for(const n of near(p.q,p.r)){const cost=p.c+(t(n.q,n.r)==='water'?2:1)+Math.max(0,h(n.q,n.r)-h(p.q,p.r));if(cost<=u.move&&!occupied(n.q,n.r,u.id)&&(!out.has(key(n.q,n.r))||cost<out.get(key(n.q,n.r)))){out.set(key(n.q,n.r),cost);q.push({...n,c:cost})}}}out.delete(key(u.q,u.r));return out}
function line(a,b){const A=cube(a.q,a.r),B=cube(b.q,b.r),n=dist(a,b),z=[];for(let i=1;i<n;i++){const f=i/n,x=A.x+(B.x-A.x)*f,y=A.y+(B.y-A.y)*f,zz=A.z+(B.z-A.z)*f;let rx=Math.round(x),ry=Math.round(y),rz=Math.round(zz),dx=Math.abs(rx-x),dy=Math.abs(ry-y),dz=Math.abs(rz-zz);if(dx>dy&&dx>dz)rx=-ry-rz;else if(dy>dz)ry=-rx-rz;else rz=-rx-ry;const r=rz,q=rx+(r-(r&1))/2;z.push({q,r})}return z}function los(a,b){const sight=Math.max(h(a.q,a.r),h(b.q,b.r))+1;return!line(a,b).some(p=>h(p.q,p.r)>sight||(t(p.q,p.r)==='ridge'&&h(p.q,p.r)>=sight))}function range(a,b){return dist(a,b)<=a.range+Math.max(0,h(a.q,a.r)-h(b.q,b.r))&&los(a,b)}
