function deselect(){state.selected=null;state.phase='select';document.querySelector('#deselectBtn').disabled=true;render()}
function clickUnit(e){if(state.turn!=='player'||state.over)return;const u=state.units.find(x=>x.id===e.currentTarget.dataset.id),s=state.units.find(x=>x.id===state.selected);if(s&&s.heal&&u.team===s.team&&u.id!==s.id&&u.hp<u.maxHp&&range(s,u)){healUnit(s,u);return}if(u.team==='player'){if(u.done)return;if(s&&s.id===u.id){if(state.phase==='move'){state.phase='attack';render()}else finish(s);return}if(s&&state.phase==='attack')return;state.inspected=null;state.selected=u.id;state.phase='move';u.shots=u.size;document.querySelector('#deselectBtn').disabled=false;render()}else if(s&&s.shots>0&&range(s,u)&&!s.heal){combat(s,u);s.shots--;if(s.shots<=0||!state.units.some(x=>x.team==='enemy'&&x.hp>0&&range(s,x)))finish(s);else{state.phase='attack';render()}}else{state.inspected=u.id;render()}}
function hex(e){if(state.turn!=='player')return;const u=state.units.find(x=>x.id===state.selected),q=+e.currentTarget.dataset.q,r=+e.currentTarget.dataset.r;if(state.phase==='move'&&u&&reach(u).has(key(q,r))){u.q=q;u.r=r;state.phase='attack';state.log.push(u.name+' advanced to elevation '+h(q,r)+'.');render()}else if(u)deselect()}
function combat(a,d){const high=Math.max(0,h(a.q,a.r)-h(d.q,d.r)),cover=h(d.q,d.r)+(t(d.q,d.r)==='ridge'?1:0),damage=Math.max(1,a.attack+high+Math.floor(Math.random()*3)-d.defense-Math.floor(cover/2));d.hp=Math.max(0,d.hp-damage);state.log.push(a.name+' hit '+d.name+' for '+damage+'.'+(d.hp===0?' Destroyed!':''));winCheck()}
